from rdkit import Chem
mol = Chem.MolFromSmiles("Cl[Ru](Cl)(=Cc1ccccc1)(P(C1CCCCC1)(C2CCCCC2)(C3CCCCC3))(P(C4CCCCC4)(C5CCCCC5)(C6CCCCC6))")
print("heavy:", mol.GetNumAtoms())
for a in mol.GetAtoms():
    if a.GetSymbol()=="P":
        print(a.GetIdx(), "neighbors:", [n.GetIdx() for n in a.GetNeighbors()], "implicit H:", a.GetNumImplicitHs())
mh = Chem.AddHs(mol)
print("with H:", mh.GetNumAtoms())
for a in mh.GetAtoms():
    if a.GetSymbol()=="H":
        nb = [n.GetIdx() for n in a.GetNeighbors()]
        if mh.GetAtomWithIdx(nb[0]).GetSymbol() not in ("C",):
            print("H", a.GetIdx(), "on", mh.GetAtomWithIdx(nb[0]).GetSymbol(), nb)
EOF
